-- Manual visual review of every farm/food image (decoding and viewing each
-- base64 photo) turned up three genuine mismatches from the original
-- Wikipedia backfill, all keyword-substring collisions:
--   - "Watermelon" showed a photo of a plastic water bottle in a field.
--   - "Malta Guinness 330ml" showed a different brand's malt drink bottle
--     ("Malta Hatuey").
--   - "Supermalt 330ml" showed a Coca-Cola bottle photo.
-- Replaced with a real watermelon-on-the-vine photo, the actual Malta
-- Guinness bottle, and a generic malted-grain photo (no correct branded
-- Supermalt photo exists on Wikimedia Commons, so this uses the same
-- generic-ingredient fallback pattern already used for other packaged
-- products like Nescafe and Shito). These three previously had a WRONG
-- image (not a missing one), so the UPDATE is unconditional rather than
-- IS NULL-guarded - the correct value is idempotent to reapply on every
-- restart, unlike V33's copy-between-rows approach.

UPDATE marketplace_posts
SET image_url = 'data:image/jpeg;base64,'
WHERE title = 'Watermelon' AND domain = 'farm';

UPDATE product_batches b
SET image_url = mp.image_url
FROM marketplace_posts mp
WHERE mp.product_batch_id = b.id
  AND mp.title = 'Watermelon' AND mp.domain = 'farm';

UPDATE marketplace_posts
SET image_url = 'data:image/jpeg;base64,'
WHERE title = 'Malta Guinness 330ml' AND domain = 'food';

UPDATE product_batches b
SET image_url = mp.image_url
FROM marketplace_posts mp
WHERE mp.product_batch_id = b.id
  AND mp.title = 'Malta Guinness 330ml' AND mp.domain = 'food';

UPDATE marketplace_posts
SET image_url = 'data:image/jpeg;base64,'
WHERE title = 'Supermalt 330ml' AND domain = 'food';

UPDATE product_batches b
SET image_url = mp.image_url
FROM marketplace_posts mp
WHERE mp.product_batch_id = b.id
  AND mp.title = 'Supermalt 330ml' AND mp.domain = 'food';
